The prior simulation still missed an end-state rule: pistons 2 and 3 can release the ball in position 1 even when their own struck position is empty. I’m correcting that and recomputing the maximum.
```python
marker = search_result
states_final = {((1, 2, 3), 4): 1.0}
win_final = [0.0] * 101

for step in range(1000):
    next_states = {}
    for (plat, nxt), mass in states_final.items():
        padded = list(plat) + [None] * (3 - len(plat))
        for pos in range(3):
            q = mass / 3.0
            if pos == 0:
                if padded[0] is not None:
                    win_final[padded[0]] += q
                updated = [padded[1], padded[2], None]
            elif pos == 1:
                if padded[0] is not None:
                    # Position 1 is released, not ejected.
                    updated = [padded[2], None, None]
                else:
                    updated = [None, None, None]
                if padded[1] is not None:
                    win_final[padded[1]] += q
            else:
                if padded[0] is not None:
                    updated = [padded[1], None, None]
                else:
                    updated = [None, None, None]
                if padded[2] is not None:
                    win_final[padded[2]] += q
            next_nxt = nxt
            while len([x for x in updated if x is not None]) < 3 and next_nxt <= 100:
                for j in range(3):
                    if updated[j] is None:
                        updated[j] = next_nxt
                        next_nxt += 1
                        break
            compact = tuple(x for x in updated if x is not None)
            key = (compact, next_nxt)
            next_states[key] = next_states.get(key, 0.0) + q
    states_final = {k: v for k, v in next_states.items() if v > 1e-14}
    if not states_final:
        break

ranking_final = sorted(((win_final[i], i) for i in range(1, 101)), reverse=True)
best_final = ranking_final[0]
print(f"best_ball={best_final[1]}; probability={best_final[0]:.12f}; top10={ranking_final[:10]}; context_used={len(marker)}")
